/bin/zsh -lc "python3 - <<'PY'
import json,pathlib,re
for c in ['case-06','case-07']:
 p=pathlib.Path(c);rows=[json.loads(x) for x in (p/'controller-audit.jsonl').read_text().splitlines()]
 print(c,'API count',sum(x['path'].startswith('/api/') for x in rows))
 for i,x in enumerate(rows,1):
  if x['path']=='/api/services' or i>len(rows)-15: print(i,json.dumps(x))
